def check_divisibility(n):
    # We need to check if n * (n * (n - 1) + 2) is divisible by 4.
    P_n = n * (n * (n - 1) + 2)
    return P_n % 4 == 0

n_values = range(5, 16)
results = {n: check_divisibility(n) for n in n_values}

print("Results for n=5 to n=15:")
for n, result in results.items():
    print(f"n={n}: Satisfies condition? {result}")
